// ============================================================================
// Types — Server response shapes (raw JSON from Hono routes)
// ============================================================================

/** Response shape for a created sale */
export interface SaleResponse {
  /** The created sale header */
  sale: Record<string, unknown>
  /** The payment record for this sale */
  payment: Record<string, unknown>
  /** All line items for this sale */
  lineItems: Record<string, unknown>[]
}

/** Error response from POST /sales */
export interface SaleError {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

// ============================================================================
// Checkout Service — calls POST /api/sales
// ============================================================================

const API_BASE = ''

/**
 * Submit a checkout to the server.
 *
 * Calls `POST /api/sales` with the cart payload and returns the created sale
 * data, or throws on failure.
 *
 * @param payload — Checkout payload from cart store
 * @returns Sale response with sale header, payment, and line items
 */
export async function submitCheckout(payload: CheckoutPayload): Promise<SaleResponse> {
  const response = await fetch(`${API_BASE}/api/sales`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  })

  if (!response.ok) {
    const errorBody = (await response.json().catch(() => ({}))) as SaleError
    // Re-throw with the server's error message for display
    throw new Error(errorBody.error ?? `Checkout failed with status ${response.status}`)
  }

  return (await response.json()) as SaleResponse
}

/**
 * Extract sale number and total from a successful checkout response.
 */
export function parseCheckoutSuccess(response: SaleResponse): CheckoutSuccess {
  const sale = response.sale as Record<string, unknown>
  return {
    saleNumber: String(sale.sale_number ?? ''),
    totalGross: Number(sale.total_gross ?? 0),
  }
}

import { useState, useRef, useEffect, useCallback } from 'react'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { useCartStore, type PartCatalogItem } from '../store'

// ============================================================================
// Types
// ============================================================================

interface PartsSearchResponse {
  parts: PartCatalogItem[]
  total: number
}

/** Payload for POST /parts/special */
interface SpecialProductPayload {
  name: string
  priceNet: number
  vatRateBasisPoints?: number
}

/** Response from POST /parts/special */
interface SpecialProductResponse extends PartCatalogItem {}

// ============================================================================
// Component — Parts Search + Barcode Input
// ============================================================================

export function PartsSearch() {
  const addLineItem = useCartStore((s) => s.addLineItem)
  const [searchTerm, setSearchTerm] = useState('')
  const [barcodeInput, setBarcodeInput] = useState('')
  const [barcodeError, setBarcodeError] = useState<string | null>(null)
  const [results, setResults] = useState<PartCatalogItem[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [highlightedIndex, setHighlightedIndex] = useState(-1)
  const [isDropdownOpen, setIsDropdownOpen] = useState(false)
  // Special form state — opened via button or Ctrl+N shortcut
  const [specialFormOpen, setSpecialFormOpen] = useState(false)

  const searchRef = useRef<HTMLInputElement>(null)

  // Global keyboard shortcut: Ctrl+N opens the Special product form from anywhere on the page
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'n') {
        e.preventDefault()
        setSpecialFormOpen(true)
      }
    }

    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [])

  // Debounced text search — fetches parts from GET /api/parts?search=
  useEffect(() => {
    if (!searchTerm.trim()) {
      setResults([])
      setIsDropdownOpen(false)
      return
    }

    const timer = setTimeout(async () => {
      setIsLoading(true)
      try {
        const response = await fetch(`/api/parts?search=${encodeURIComponent(searchTerm.trim())}`)
        if (response.ok) {
          const data = (await response.json()) as PartsSearchResponse
          setResults(data.parts)
          setIsDropdownOpen(data.parts.length > 0)
        } else {
          setResults([])
          setIsDropdownOpen(false)
        }
      } catch {
        // Silently fail — show empty results
        setResults([])
        setIsDropdownOpen(false)
      } finally {
        setIsLoading(false)
      }
    }, 250)

    return () => clearTimeout(timer)
  }, [searchTerm])

  /** Add a part to cart and reset the search input for rapid next-item entry */
  const handleAddToCart = useCallback(
    (part: PartCatalogItem) => {
      addLineItem(part)
      setSearchTerm('')
      setResults([])
      setIsDropdownOpen(false)
      setHighlightedIndex(-1)
      searchRef.current?.focus()
    },
    [addLineItem]
  )

  // Keyboard navigation for the dropdown
  const handleSearchKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (!isDropdownOpen || results.length === 0) return

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault()
          setHighlightedIndex((prev) => Math.min(prev + 1, results.length - 1))
          break
        case 'ArrowUp':
          e.preventDefault()
          setHighlightedIndex((prev) => Math.max(prev - 1, 0))
          break
        case 'Enter':
          e.preventDefault()
          if (highlightedIndex >= 0 && highlightedIndex < results.length) {
            handleAddToCart(results[highlightedIndex])
          } else if (results.length === 1) {
            // Single result — auto-select on Enter
            handleAddToCart(results[0])
          }
          break
        case 'Escape':
          e.preventDefault()
          setIsDropdownOpen(false)
          setHighlightedIndex(-1)
          break
      }
    },
    [isDropdownOpen, results, highlightedIndex, handleAddToCart]
  )

  // Barcode scan — adds to cart on Enter or blur
  const handleBarcodeSubmit = useCallback(async () => {
    if (!barcodeInput.trim()) return

    setIsLoading(true)
    try {
      const response = await fetch(`/api/parts?search=${encodeURIComponent(barcodeInput.trim())}`)
      if (response.ok) {
        const data = (await response.json()) as PartsSearchResponse
        // Barcode scanners send exact matches — take the first result
        if (data.parts.length > 0) {
          addLineItem(data.parts[0])
          setBarcodeInput('')
          setBarcodeError(null)
          return
        }
        // No part found with this barcode
        setBarcodeError('No part found with this barcode')
      }
    } catch {
      // Silently fail — don't show error on network issues
    } finally {
      setIsLoading(false)
      if (!barcodeError) {
        setBarcodeInput('')
      }
    }
  }, [barcodeInput, addLineItem])

  const handleBarcodeKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Enter') {
        e.preventDefault()
        handleBarcodeSubmit()
      }
    },
    [handleBarcodeSubmit]
  )

  return (
    <div className="flex flex-col gap-3">
      {/* Barcode scan input — dedicated field for keyboard wedge scanners */}
      <div>
        <Label htmlFor="barcode-input" className="text-sm font-medium text-muted-foreground mb-1 block">
          Barcode Scan
        </Label>
        <Input
          id="barcode-input"
          ref={searchRef as React.RefObject<HTMLInputElement>}
          placeholder="Scan or type barcode..."
          value={barcodeInput}
          onChange={(e) => {
            setBarcodeInput(e.target.value)
            if (barcodeError) setBarcodeError(null)
          }}
          onKeyDown={handleBarcodeKeyDown}
          onBlur={handleBarcodeSubmit}
          disabled={isLoading}
        />
      </div>

      {barcodeError && (
        <p className="text-xs text-destructive mt-1">{barcodeError}</p>
      )}

      {/* Text search for parts by name */}
      <div className="relative">
        <Label htmlFor="parts-search" className="text-sm font-medium text-muted-foreground mb-1 block">
          Search Parts
        </Label>
        <Input
          id="parts-search"
          placeholder="Search by name..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          onKeyDown={handleSearchKeyDown}
          disabled={isLoading}
          aria-autocomplete="list"
          aria-expanded={isDropdownOpen}
          aria-controls="parts-search-results"
        />

        {/* Compact select-style dropdown */}
        {isDropdownOpen && results.length > 0 && (
          <div
            id="parts-search-results"
            role="listbox"
            className="absolute z-50 w-full mt-1 border rounded-md bg-background shadow-lg max-h-48 overflow-y-auto"
          >
            {results.map((part, index) => {
              const isHighlighted = index === highlightedIndex
              const isOutOfStock = part.quantityOnHand <= 0

              return (
                <button
                  key={part.id}
                  type="button"
                  role="option"
                  aria-selected={isHighlighted}
                  onClick={() => handleAddToCart(part)}
                  disabled={isOutOfStock || isLoading}
                  className={`w-full text-left px-3 py-2 border-b last:border-b-0 flex items-center justify-between transition-colors ${
                    isHighlighted ? 'bg-accent' : ''
                  } ${
                    isOutOfStock
                      ? 'opacity-50 cursor-not-allowed'
                      : 'hover:bg-accent/70 cursor-pointer'
                  }`}
                >
                  <div className="flex-1 min-w-0">
                    <div className="font-medium truncate">{part.name}</div>
                    <div className="text-xs text-muted-foreground flex items-center gap-2">
                      <span>{part.barcode}</span>
                      <span>·</span>
                      <span>Stock: {part.quantityOnHand}</span>
                    </div>
                  </div>
                  <div className="ml-3 flex items-center gap-2 shrink-0">
                    <span className="text-sm font-mono">{formatPrice(part.priceNet)}</span>
                    {!isOutOfStock && (
                      <span className="text-xs text-muted-foreground">+ Add</span>
                    )}
                  </div>
                </button>
              )
            })}
          </div>
        )}

        {/* No results message */}
        {!isLoading && searchTerm.trim() && !isDropdownOpen && (
          <div className="text-sm text-muted-foreground text-center py-4">No parts found</div>
        )}
      </div>

      {isLoading && (
        <div className="text-sm text-muted-foreground text-center py-4">Loading...</div>
      )}

      {/* Special product creation button / inline form */}
      <SpecialProductForm
        isOpen={specialFormOpen}
        onToggle={() => setSpecialFormOpen((prev) => !prev)}
        onCreated={(part) => {
          handleAddToCart(part)
          setSpecialFormOpen(false)
        }}
      />
    </div>
  )
}

// ============================================================================
// Inline Special Product Creation Form
// ============================================================================

interface SpecialProductFormProps {
  isOpen: boolean
  onToggle: () => void
  onCreated: (part: PartCatalogItem) => void
}

function SpecialProductForm({ isOpen, onToggle, onCreated }: SpecialProductFormProps) {
  const [name, setName] = useState('')
  const [priceCents, setPriceCents] = useState('')
  const [vatRateBps, setVatRateBps] = useState(2100) // default: standard 21%
  const [errors, setErrors] = useState<{ name?: string; price?: string }>({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const nameRef = useRef<HTMLInputElement>(null)

  /** Validate form fields — returns true if valid */
  const validate = useCallback((): boolean => {
    const newErrors: { name?: string; price?: string } = {}

    if (!name.trim()) {
      newErrors.name = 'Name is required'
    } else if (name.trim().length < 2) {
      newErrors.name = 'Name must be at least 2 characters'
    }

    const parsedPrice = parseInt(priceCents, 10)
    if (!priceCents || isNaN(parsedPrice)) {
      newErrors.price = 'Price is required (in cents)'
    } else if (parsedPrice <= 0) {
      newErrors.price = 'Price must be greater than 0'
    } else if (!Number.isInteger(Number(priceCents))) {
      newErrors.price = 'Price must be a whole number of cents'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }, [name, priceCents])

  /** Submit the special product creation form */
  const handleSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault()

      if (!validate()) return

      setIsSubmitting(true)
      setErrors({})

      try {
        const parsedPrice = parseInt(priceCents, 10)
        const payload: SpecialProductPayload = {
          name: name.trim(),
          priceNet: parsedPrice,
          vatRateBasisPoints: vatRateBps,
        }

        const response = await fetch('/api/parts/special', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })

        if (!response.ok) {
          const errorData = await response.json().catch(() => null)
          throw new Error(errorData?.error || `Server error: ${response.status}`)
        }

        const createdPart = (await response.json()) as SpecialProductResponse
        onCreated(createdPart)

        // Reset form state after successful creation
        setName('')
        setPriceCents('')
        setVatRateBps(2100)
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Failed to create special product'
        setErrors({ price: message })
      } finally {
        setIsSubmitting(false)
      }
    },
    [name, priceCents, vatRateBps, validate, onCreated]
  )

  /** Reset form state when closing */
  useEffect(() => {
    if (!isOpen) {
      setName('')
      setPriceCents('')
      setVatRateBps(2100)
      setErrors({})
    } else {
      // Opening — focus the name input
      setTimeout(() => nameRef.current?.focus(), 50)
    }
  }, [isOpen])

  /** VAT rate options */
  const vatOptions = [
    { label: 'Standard (21%)', value: 2100, shortLabel: 'Std' },
    { label: 'Reduced (6%)', value: 600, shortLabel: 'Red' },
    { label: 'Zero (0%)', value: 0, shortLabel: 'Zero' },
  ]

  return (
    <div className="mt-2">
      {/* Toggle button — visible when form is closed */}
      {!isOpen && (
        <Button variant="outline" size="sm" onClick={onToggle} className="w-full text-sm">
          + Create Special Product
        </Button>
      )}

      {/* Inline expandable form */}
      {isOpen && (
        <form onSubmit={handleSubmit} className="mt-2 space-y-3 p-3 border rounded-md bg-muted/30">
          <div className="text-sm font-medium text-foreground">New Special Product</div>

          {/* Name field */}
          <div>
            <Label htmlFor="special-name" className="text-xs mb-1 block">
              Name *
            </Label>
            <Input
              id="special-name"
              ref={nameRef}
              placeholder="Product name..."
              value={name}
              onChange={(e) => {
                setName(e.target.value)
                if (errors.name) setErrors((prev) => ({ ...prev, name: undefined }))
              }}
              disabled={isSubmitting}
              aria-invalid={!!errors.name}
            />
            {errors.name && <p className="text-xs text-destructive mt-1">{errors.name}</p>}
          </div>

          {/* Price field */}
          <div>
            <Label htmlFor="special-price" className="text-xs mb-1 block">
              Price (cents) *
            </Label>
            <Input
              id="special-price"
              type="number"
              inputMode="numeric"
              placeholder="e.g. 2500 for €25.00"
              value={priceCents}
              onChange={(e) => {
                setPriceCents(e.target.value)
                if (errors.price) setErrors((prev) => ({ ...prev, price: undefined }))
              }}
              disabled={isSubmitting}
              aria-invalid={!!errors.price}
            />
            {errors.price && <p className="text-xs text-destructive mt-1">{errors.price}</p>}
          </div>

          {/* VAT rate toggle */}
          <div>
            <Label className="text-xs mb-1 block">VAT Rate</Label>
            <div className="flex gap-2" role="radiogroup" aria-label="VAT rate selection">
              {vatOptions.map((option) => (
                <button
                  key={option.value}
                  type="button"
                  onClick={() => setVatRateBps(option.value)}
                  className={`px-3 py-1.5 text-xs rounded-md border transition-colors ${
                    vatRateBps === option.value
                      ? 'bg-primary text-primary-foreground border-primary'
                      : 'border-input bg-background hover:bg-accent'
                  }`}
                  role="radio"
                  aria-checked={vatRateBps === option.value}
                >
                  {option.shortLabel} ({option.label.split(' ')[1]})
                </button>
              ))}
            </div>
          </div>

          {/* Submit button */}
          <Button type="submit" disabled={isSubmitting} size="sm" className="w-full">
            {isSubmitting ? 'Creating...' : 'Create & Add to Cart'}
          </Button>
        </form>
      )}
    </div>
  )
}

