/** Format cents to currency string */
function formatPrice(cents: number): string {
  const euros = (cents / 100).toFixed(2)
  return `€${euros}`
}

import { z } from 'zod'

// ---------------------------------------------------------------------------
// Shared Line Item Variant Definitions
//
// Each variant is a composable building block that modules import and use to
// construct their own discriminated union schemas. This eliminates duplication
// of base fields (description, quantity, unitPriceNet, vatRateId, discountPercent)
// across repair, quote, customer-order, and sales validation schemas.
// ---------------------------------------------------------------------------

/** Base fields shared by all line item types */
const baseLineItemFields = {
  description: z.string().min(1, 'description is required').max(500),
  quantity: z.number().int().positive('quantity must be a positive integer'),
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be non-negative'),
  vatRateId: z.string().min(1, 'vatRateId is required'),
  discountPercent: z.number().int().min(0).max(10000).nullable().optional(),
}

// ---------------------------------------------------------------------------
// Part Variant
// ---------------------------------------------------------------------------

/**
 * A reusable part line item variant definition.
 * Modules compose this into their own discriminated union schemas.
 */
export const partLineItemVariant = {
  /** Discriminator value for the `lineType` field */
  lineType: 'part' as const,

  /** Build a Zod schema object for use in a discriminated union */
  toSchema() {
    return z.object({
      ...baseLineItemFields,
      lineType: z.literal('part'),
      partId: z.string().min(1, 'partId is required'),
    })
  },
}

/** Input type for a part line item */
export type PartLineItemInput = z.infer<ReturnType<typeof partLineItemVariant.toSchema>>

// ---------------------------------------------------------------------------
// Labor Variant
// ---------------------------------------------------------------------------

/**
 * A reusable labor line item variant definition.
 * Modules compose this into their own discriminated union schemas.
 * All labor-specific fields are nullable — modules may add refinements
 * to enforce stricter requirements (e.g., requiring laborServiceId).
 */
export const laborLineItemVariant = {
  /** Discriminator value for the `lineType` field */
  lineType: 'labor' as const,

  /** Build a Zod schema object for use in a discriminated union */
  toSchema() {
    return z.object({
      ...baseLineItemFields,
      lineType: z.literal('labor'),
      laborServiceId: z.string().nullable().optional(),
      minutesWorked: z.number().int().positive().nullable().optional(),
      hourlyRateSnapshot: z.number().int().nonnegative().nullable().optional(),
    })
  },
}

/** Input type for a labor line item */
export type LaborLineItemInput = z.infer<ReturnType<typeof laborLineItemVariant.toSchema>>

// ---------------------------------------------------------------------------
// Bicycle Variant
// ---------------------------------------------------------------------------

/**
 * A reusable bicycle line item variant definition.
 * Modules compose this into their own discriminated union schemas.
 * All bicycle-specific fields are nullable — modules may add refinements
 * to enforce stricter requirements as needed.
 */
export const bicycleLineItemVariant = {
  /** Discriminator value for the `lineType` field */
  lineType: 'bicycle' as const,

  /** Build a Zod schema object for use in a discriminated union */
  toSchema() {
    return z.object({
      ...baseLineItemFields,
      lineType: z.literal('bicycle'),
      bicycleId: z.string().nullable().optional(),
      bicycleBrand: z.string().max(100).nullable().optional(),
      bicycleModel: z.string().max(200).nullable().optional(),
      bicycleYear: z.number().int().min(1900).max(new Date().getFullYear() + 1).nullable().optional(),
      bicycleColor: z.string().max(50).nullable().optional(),
      bicycleFrameSize: z.string().max(20).nullable().optional(),
    })
  },
}

/** Input type for a bicycle line item */
export type BicycleLineItemInput = z.infer<ReturnType<typeof bicycleLineItemVariant.toSchema>>

import { z } from 'zod'
import { partLineItemVariant, laborLineItemVariant, bicycleLineItemVariant } from './line-item-variants.js'

/** Payment method accepted at checkout */
export const paymentMethodSchema = z.enum(['cash', 'card'])

export type PaymentMethod = z.infer<typeof paymentMethodSchema>

/** A single line item in a sale cart / creation request — discriminated union of part, labor, bicycle */
export const cartLineItemSchema = z.discriminatedUnion('lineType', [
  partLineItemVariant.toSchema(),
  laborLineItemVariant.toSchema(),
  bicycleLineItemVariant.toSchema(),
])

export type CartLineItem = z.infer<typeof cartLineItemSchema>

/** Full input for creating a direct sale at checkout */
export const createDirectSaleInputSchema = z.object({
  /** Optional customer ID — null/absent means walk-in */
  customerId: z.string().nullable().optional(),
  /** Payment method for the full amount */
  paymentMethod: paymentMethodSchema,
  /** Line items being purchased (part, labor, or bicycle) */
  lineItems: z.array(cartLineItemSchema).min(1, 'At least one line item is required'),
})

export type CreateDirectSaleInput = z.infer<typeof createDirectSaleInputSchema>

import { Hono } from 'hono'
import {
  createDirectSale,
  voidSale,
  type SaleResult,
  InsufficientStockError,
  SaleNotFoundError,
  listSales,
  findSaleById,
  findLineItemsBySaleId,
  findPaymentsBySaleId,
  findMovementsBySaleId
} from '../services/sale.service.js'

const salesRoutes = new Hono()

// ============================================================================
// POST /sales — Create a direct sale
// ============================================================================

/**
 * Error response shape.
 */
interface ErrorResponse {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

salesRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result: SaleResult = await createDirectSale(rawInput)

    return c.json(
      {
        sale: Object.fromEntries(Object.entries(result.sale)),
        payment: Object.fromEntries(Object.entries(result.payment)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item)))
      },
      201
    )
  } catch (err) {
    if (err instanceof InsufficientStockError) {
      return c.json(
        {
          error: 'Insufficient stock',
          code: 'INSUFFICIENT_STOCK',
          shortfalls: err.shortfalls
        } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid sale input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /sales] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /sales — List recent sales history
// ============================================================================

interface SalesListResponse {
  /** Array of sale records (newest first) */
  sales: Record<string, unknown>[]
  /** Total count of all sales */
  total: number
}

salesRoutes.get('/', async (c) => {
  const limit = Math.min(parseInt(c.req.query('limit') ?? '50', 10) || 50, 200)
  const customerId = c.req.query('customerId') as string | undefined

  const saleRows = await listSales({
    limit,
    customerId: customerId ?? null,
  })
  const total = await listSales({
    limit: 999999,
    customerId: customerId ?? null,
  }).then(rows => rows.length)

  return c.json({
    sales: saleRows.map(row => Object.fromEntries(Object.entries(row))),
    total
  } as SalesListResponse)
})

// ============================================================================
// GET /sales/:id — Get a single sale with full details
// ============================================================================

interface SaleDetailResponse {
  /** The sale header */
  sale: Record<string, unknown>
  /** Line items for this sale */
  lineItems: Record<string, unknown>[]
  /** Payments allocated to this sale */
  payments: Record<string, unknown>[]
  /** Stock movements referencing this sale */
  stockMovements: Record<string, unknown>[]
}

salesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const sale = await findSaleById(id)
  if (!sale) {
    return c.json({ error: 'Sale not found', code: 'NOT_FOUND' }, 404)
  }

  const [lineItems, payments, stockMovements] = await Promise.all([
    findLineItemsBySaleId(id),
    findPaymentsBySaleId(id),
    findMovementsBySaleId(id)
  ])

  return c.json({
    sale: Object.fromEntries(Object.entries(sale)),
    lineItems: lineItems.map(item => Object.fromEntries(Object.entries(item))),
    payments: payments.map(payment => Object.fromEntries(Object.entries(payment))),
    stockMovements: stockMovements.map(mvmt => Object.fromEntries(Object.entries(mvmt)))
  } as SaleDetailResponse)
})

// ============================================================================
// PATCH /sales/:id/void — Void a completed sale
// ============================================================================

salesRoutes.patch('/:id/void', async (c) => {
  const id = c.req.param('id')

  try {
    const updatedSale = await voidSale(id)

    return c.json({
      sale: Object.fromEntries(Object.entries(updatedSale))
    })
  } catch (err) {
    if (err instanceof SaleNotFoundError) {
      return c.json(
        { error: 'Sale not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && err.message.includes('already voided')) {
      return c.json(
        { error: err.message, code: 'ALREADY_VOIDED' },
        409
      )
    }

    console.error('[PATCH /sales/:id/void] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

export default salesRoutes

import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { useCartStore, VAT_RATES } from '../store'

// ============================================================================
// Component — Cart Display
// ============================================================================

export function CartDisplay() {
  const lineItems = useCartStore((s) => s.lineItems)
  const subtotalNet = useCartStore((s) => s.subtotalNet)
  const vatTotal = useCartStore((s) => s.vatTotal)
  const totalGross = useCartStore((s) => s.totalGross)
  const updateQuantity = useCartStore((s) => s.updateQuantity)
  const removeLineItem = useCartStore((s) => s.removeLineItem)
  const changeVatRate = useCartStore((s) => s.changeVatRate)

  if (lineItems.length === 0) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="text-center text-muted-foreground py-8">
            Cart is empty — search for parts above to add items
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card>
      <CardContent className="p-0">
        {/* Line items list */}
        <div className="divide-y max-h-[400px] overflow-y-auto">
          {lineItems.map((item) => (
            <CartLineItemRow
              key={item.partId}
              item={item}
              onUpdateQuantity={updateQuantity}
              onVatChange={changeVatRate}
              onRemove={removeLineItem}
            />
          ))}
        </div>

        {/* Running totals */}
        <div className="border-t p-4 space-y-1">
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">Subtotal (net)</span>
            <span className="font-mono">{formatPrice(subtotalNet)}</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">VAT</span>
            <span className="font-mono">{formatPrice(vatTotal)}</span>
          </div>
          <div className="flex justify-between font-bold text-base pt-2 border-t">
            <span>Total (gross)</span>
            <span className="font-mono">{formatPrice(totalGross)}</span>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

// ============================================================================
// Sub-component — Single Line Item Row
// ============================================================================

interface CartLineItemRowProps {
  item: ReturnType<typeof useCartStore.getState>['lineItems'][number]
  onUpdateQuantity: (partId: string, quantity: number) => void
  onVatChange: (partId: string, newVatRateId: keyof typeof VAT_RATES) => void
  onRemove: (partId: string) => void
}

function CartLineItemRow({ item, onUpdateQuantity, onVatChange, onRemove }: CartLineItemRowProps) {
  return (
    <div className="p-3 flex items-center gap-3">
      {/* VAT rate selector */}
      <select
        value={item.vatRateId}
        onChange={(e) => onVatChange(item.partId, e.target.value as keyof typeof VAT_RATES)}
        className="h-7 px-1 text-xs border rounded bg-background font-mono shrink-0"
        title="VAT rate"
      >
        <option value="vat-zero">0%</option>
        <option value="vat-reduced">6%</option>
        <option value="vat-standard">21%</option>
      </select>

      {/* Quantity controls */}
      <div className="flex items-center gap-1 shrink-0">
        <Button
          variant="outline"
          size="sm"
          onClick={() => onUpdateQuantity(item.partId, item.quantity - 1)}
          className="h-7 w-7 p-0"
        >
          −
        </Button>
        <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
        <Button
          variant="outline"
          size="sm"
          onClick={() => onUpdateQuantity(item.partId, item.quantity + 1)}
          className="h-7 w-7 p-0"
        >
          +
        </Button>
      </div>

      {/* Part info */}
      <div className="flex-1 min-w-0">
        <div className="text-sm font-medium truncate">{item.name}</div>
        <div className="text-xs text-muted-foreground flex items-center gap-2">
          <span>{formatPrice(item.priceNet)} each × {item.quantity}</span>
          <span className="text-muted-foreground/60">·</span>
          <span className="text-muted-foreground/80 font-mono">
            VAT: {VAT_RATES[item.vatRateId] / 100}%
          </span>
        </div>
      </div>

      {/* Line total */}
      <div className="text-right shrink-0">
        <div className="font-mono text-sm font-medium">{formatPrice(item.lineTotalGross)}</div>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => onRemove(item.partId)}
          className="h-5 px-1 text-xs text-destructive hover:text-destructive"
        >
          ✕
        </Button>
      </div>
    </div>
  )
}

// ============================================================================
// Helpers
// ============================================================================

function formatPrice(cents: number): string {
  const euros = (cents / 100).toFixed(2)
  return `€${euros}`
}

